package studio.jiayu.neoagent;

import android.app.Activity;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** Explicit foreground update checks. No token, schedule, silent installation, or model endpoint. */
public final class AppUpdater {
 public interface Listener {void changed(JSONObject state);boolean installationAllowed();}
 private static final String FEED="https://raw.githubusercontent.com/"+UpdateRules.REPO+"/main/guides/neo-agent-touch/update.json";
 private static final String API="https://api.github.com/repos/"+UpdateRules.REPO+"/releases?per_page=100&page=";
 private final Activity activity;private final Listener listener;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private volatile boolean closed;private volatile HttpURLConnection connection;private boolean busy,awaitingPermission;private long generation;private int progress;private String phase="idle",message="点击即可检查官方 Beta 与正式版更新",version="",notes="";private long code;private UpdateRules.Candidate candidate;
 public AppUpdater(Activity activity,Listener listener){this.activity=activity;this.listener=listener;try{PackageInfo p=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0);version=p.versionName;code=p.getLongVersionCode();}catch(Exception ignored){phase="error";message="无法读取当前应用版本";}}
 public JSONObject state(){JSONObject s=new JSONObject();try{s.put("currentVersion",version).put("currentCode",code).put("phase",phase).put("message",message).put("busy",busy).put("progress",progress).put("available",candidate!=null).put("latestVersion",candidate==null?"":candidate.version).put("size",candidate==null?0:candidate.size).put("notes",notes).put("releaseUrl",releaseUrl());}catch(Exception ignored){}return s;}
 private void emit(){if(!closed)listener.changed(state());}
 private String releaseUrl(){return candidate==null?UpdateRules.RELEASES:UpdateRules.RELEASES+"/tag/"+candidate.tag;}
 private void post(long token,Runnable r){main.post(()->{if(!closed&&generation==token&&!activity.isFinishing())r.run();});}
 private void fail(long token,String reason){post(token,()->{busy=false;phase="error";message=reason;emit();});}
 public void check(){if(closed||busy)return;if(UpdateRules.version(version)==null){message="当前版本格式无法识别，请打开发布页查看";phase="error";emit();return;}busy=true;phase="checking";message="正在检查官方更新通道…";progress=0;candidate=null;notes="";emit();long token=++generation;worker.execute(()->{try{
   Check result;try{result=feed();}catch(Exception unavailable){result=releases();}
   final Check found=result;post(token,()->{busy=false;candidate=found.candidate;notes=found.notes;phase=candidate==null?"latest":"available";message=candidate!=null?"发现新版本，可下载并由系统确认安装":found.message;emit();});
  }catch(UpdateFailure known){fail(token,known.getMessage());}catch(Exception unavailable){fail(token,"检查更新失败，请检查网络或打开 GitHub 发布页");}});}
 private static final class Check {final UpdateRules.Candidate candidate;final String notes,message;Check(UpdateRules.Candidate candidate,String notes,String message){this.candidate=candidate;this.notes=notes;this.message=message;}}
 private Check feed()throws Exception{JSONObject j=new JSONObject(new String(fetch(FEED,65536),"UTF-8"));if(j.optInt("schema")!=1||!UpdateRules.PACKAGE.equals(j.optString("packageName")))throw new UpdateFailure("更新清单格式不正确");String v=j.getString("versionName"),tag=j.getString("tag"),name=j.getString("assetName"),url=j.getString("downloadUrl"),digest=UpdateRules.digest(j.getString("sha256"));long remoteCode=j.getLong("versionCode"),size=j.getLong("size");UpdateRules.Version parsed=UpdateRules.releaseVersion(tag);if(parsed==null||!parsed.text.equals(v)||!UpdateRules.apkName(name,v)||!UpdateRules.assetUrl(url,tag,name)||digest.isEmpty()||!UpdateRules.validSize(size)||remoteCode<=0)throw new UpdateFailure("更新清单校验未通过");UpdateRules.Version installed=UpdateRules.version(version);int order=parsed.compareTo(installed);if(order>0&&remoteCode<=code||order==0&&remoteCode!=code)throw new UpdateFailure("更新版本信息不一致");UpdateRules.Candidate c=order>0?new UpdateRules.Candidate(tag,v,name,url,size,digest,"",remoteCode):null;String text=j.optString("notes","");return new Check(c,text.substring(0,Math.min(text.length(),1600)),order<0?"当前安装版本高于官方更新通道，保留本机版本":"当前更新通道已是最新版");}
 private Check releases()throws Exception{ArrayList<UpdateRules.Candidate> all=new ArrayList<>();Map<String,String> descriptions=new HashMap<>();boolean complete=false,sawNewer=false;for(int page=1;page<=10;page++){JSONArray releases=new JSONArray(new String(fetch(API+page,2*1024*1024),"UTF-8"));for(int i=0;i<releases.length();i++){JSONObject r=releases.optJSONObject(i);if(r==null||r.optBoolean("draft"))continue;String tag=r.optString("tag_name");UpdateRules.Version v=UpdateRules.releaseVersion(tag);if(v==null)continue;sawNewer|=v.compareTo(UpdateRules.version(version))>0;JSONArray assets=r.optJSONArray("assets");if(assets==null)continue;String checksumUrl="";for(int n=0;n<assets.length();n++){JSONObject a=assets.optJSONObject(n);if(a==null)continue;String name=a.optString("name"),u=a.optString("browser_download_url");if(name.equals("SHA256SUMS.txt")&&UpdateRules.assetUrl(u,tag,name))checksumUrl=u;}
    for(int n=0;n<assets.length();n++){JSONObject a=assets.optJSONObject(n);if(a==null)continue;String name=a.optString("name"),u=a.optString("browser_download_url"),digest=UpdateRules.digest(a.optString("digest"));if(!UpdateRules.apkName(name,v.text)||!UpdateRules.assetUrl(u,tag,name)||!UpdateRules.validSize(a.optLong("size")))continue;if(digest.isEmpty()&&checksumUrl.isEmpty())continue;all.add(new UpdateRules.Candidate(tag,v.text,name,u,a.optLong("size"),digest,checksumUrl));String text=r.optString("body","");descriptions.put(tag,text.substring(0,Math.min(text.length(),1600)));}}
   if(releases.length()<100){complete=true;break;}}
  if(!complete)throw new UpdateFailure("发布记录过多，尚未完整核对，请打开发布页查看");UpdateRules.Candidate selected=UpdateRules.select(all,version);if(selected==null&&sawNewer)throw new UpdateFailure("存在较新发布，但缺少可校验的应用包，请打开发布页查看");return new Check(selected,selected==null?"":descriptions.get(selected.tag),"已核对公开应用发布，当前没有更高版本");}
 public void downloadAndInstall(){if(closed||busy)return;if(candidate==null){message="请先检查更新";emit();return;}if(!listener.installationAllowed()){phase="available";message="请先结束当前任务，再点击更新安装";emit();return;}final UpdateRules.Candidate c=candidate;busy=true;phase="downloading";message="正在下载并校验更新…";progress=0;emit();long token=++generation;worker.execute(()->{File temporary=null;try{
   String digest=c.sha256;if(digest.isEmpty())digest=UpdateRules.checksum(new String(fetch(c.checksumUrl,262144),"UTF-8"),c.name);if(digest.isEmpty())throw new UpdateFailure("发布包缺少有效 SHA-256 校验，未安装");
   boolean reuse=false;Uri ready=AppUpdateStore.uri(activity);if(ready!=null)try{File f=AppUpdateStore.verified(activity,ready);reuse=f.length()==c.size&&AppUpdateStore.hash(f).equals(digest);}catch(Exception ignored){}
   File target=AppUpdateStore.staged(activity);if(!reuse){AppUpdateStore.clear(activity);temporary=new File(AppUpdateStore.directory(activity),"incoming.apk.part");if(temporary.exists()&&!temporary.delete())throw new UpdateFailure("无法清理更新缓存");download(c,temporary,token);if(!AppUpdateStore.hash(temporary).equals(digest))throw new UpdateFailure("更新包 SHA-256 不一致，已阻止安装");verifyArchive(temporary,c);if(target.exists()&&!target.delete())throw new UpdateFailure("无法替换更新缓存");if(!temporary.renameTo(target))throw new UpdateFailure("无法保存更新文件");temporary=null;AppUpdateStore.bind(activity,c,digest);}
   verifyArchive(target,c);Uri uri=AppUpdateStore.uri(activity);AppUpdateStore.verified(activity,uri);post(token,()->{busy=false;progress=100;requestInstall();});
  }catch(UpdateFailure known){fail(token,known.getMessage());}catch(Exception failed){fail(token,"下载或校验失败，未安装；请检查网络或打开发布页");}finally{if(temporary!=null)temporary.delete();}});}
 private void verifyArchive(File apk,UpdateRules.Candidate c)throws Exception{PackageManager pm=activity.getPackageManager();PackageInfo installed=pm.getPackageInfo(activity.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES),archive=pm.getPackageArchiveInfo(apk.getAbsolutePath(),PackageManager.GET_SIGNING_CERTIFICATES);if(archive==null||!UpdateRules.archive(archive.packageName,archive.getLongVersionCode(),archive.versionName,installed.getLongVersionCode(),c.version,signers(installed),signers(archive))||c.versionCode>0&&archive.getLongVersionCode()!=c.versionCode)throw new UpdateFailure("安装包身份、版本或签名不匹配，已阻止安装");}
 private static Set<String> signers(PackageInfo info)throws Exception{Set<String> out=new HashSet<>();if(info.signingInfo==null)return out;Signature[] values=info.signingInfo.getApkContentsSigners();if(values==null)return out;for(Signature s:values){byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(s.toByteArray());StringBuilder text=new StringBuilder();for(byte b:bytes)text.append(String.format(Locale.ROOT,"%02x",b&255));out.add(text.toString());}return out;}
 private void requestInstall(){if(!listener.installationAllowed()){phase="ready";message="更新已校验保存，请结束当前任务后再点安装";emit();return;}if(!activity.getPackageManager().canRequestPackageInstalls()){awaitingPermission=true;phase="permission";message="请在系统中允许本应用安装更新，返回后继续确认";emit();try{activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));}catch(Exception unsupported){awaitingPermission=false;phase="ready";message="无法打开安装权限设置，请打开发布页手动更新";emit();}return;}launchInstaller();}
 private void launchInstaller(){if(!listener.installationAllowed()){phase="ready";message="更新已保存，请结束当前任务后再点安装";emit();return;}try{Uri uri=AppUpdateStore.uri(activity);if(uri==null)throw new IllegalStateException();Intent install=new Intent(Intent.ACTION_INSTALL_PACKAGE).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);install.setClipData(ClipData.newRawUri("Neo Agent Touch update",uri));activity.startActivity(install);phase="installing";message="已打开系统安装界面，请在手机确认；返回不代表安装成功";emit();}catch(Exception unavailable){phase="ready";message="无法启动系统安装，请打开发布页手动更新";emit();}}
 public void onResume(){if(!awaitingPermission||closed)return;awaitingPermission=false;if(!activity.getPackageManager().canRequestPackageInstalls()){phase="ready";message="尚未允许安装更新，可再次点击安装或打开发布页";emit();return;}if(!listener.installationAllowed()){phase="ready";message="更新已保存，请结束当前任务后再点安装";emit();return;}downloadAndInstall();}
 public void openRelease(){try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(releaseUrl())));}catch(Exception unavailable){message="暂时无法打开浏览器，请稍后重试";emit();}}
 private byte[] fetch(String url,int limit)throws Exception{HttpURLConnection h=open(url);try(InputStream in=h.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int count;while((count=in.read(buf))!=-1){if(closed||Thread.currentThread().isInterrupted())throw new IOException();if(out.size()+count>limit)throw new UpdateFailure("更新信息过大，未采用该响应");out.write(buf,0,count);}return out.toByteArray();}finally{h.disconnect();if(connection==h)connection=null;}}
 private HttpURLConnection open(String address)throws Exception{String url=address;for(int redirect=0;redirect<=4;redirect++){URI u=new URI(url);boolean first=redirect==0;boolean allowed=first&&(url.equals(FEED)||url.startsWith(API)&&url.substring(API.length()).matches("[1-9][0-9]?"))||UpdateRules.downloadHost(url);if(!allowed)throw new UpdateFailure("更新地址不在官方来源内");HttpURLConnection h=(HttpURLConnection)u.toURL().openConnection();connection=h;h.setInstanceFollowRedirects(false);h.setConnectTimeout(15000);h.setReadTimeout(20000);h.setRequestProperty("User-Agent","NeoAgentTouch-Updater/1.0");h.setRequestProperty("Accept","application/vnd.github+json");h.setRequestProperty("Accept-Encoding","identity");int status=h.getResponseCode();if(status==301||status==302||status==303||status==307||status==308){String location=h.getHeaderField("Location");h.disconnect();if(location==null)throw new UpdateFailure("更新来源重定向不完整");url=u.resolve(location).toString();continue;}if(status!=200){h.disconnect();if(status==403||status==429)throw new UpdateFailure("GitHub 暂时限流，未能确认更新；请稍后重试或打开发布页");throw new UpdateFailure("官方更新来源暂不可用，请稍后重试或打开发布页");}return h;}throw new UpdateFailure("更新来源重定向过多");}
 private void download(UpdateRules.Candidate c,File file,long token)throws Exception{HttpURLConnection h=open(c.url);long declared=h.getContentLengthLong();if(declared>=0&&declared!=c.size){h.disconnect();throw new UpdateFailure("更新包大小与发布信息不符，未安装");}long bytes=0,start=SystemClock.elapsedRealtime();int shown=-5;try(InputStream in=h.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] buffer=new byte[65536];int count;while((count=in.read(buffer))!=-1){if(closed||Thread.currentThread().isInterrupted()||SystemClock.elapsedRealtime()-start>180000)throw new UpdateFailure("更新下载已取消或超时");bytes+=count;if(bytes>c.size||bytes>UpdateRules.MAX_APK_BYTES)throw new UpdateFailure("更新包超过声明大小，未安装");out.write(buffer,0,count);int percent=(int)(bytes*100/c.size);if(percent==100||percent-shown>=5){shown=percent;final int p=percent;post(token,()->{progress=p;emit();});}}if(bytes!=c.size)throw new UpdateFailure("更新下载不完整，未安装");}finally{h.disconnect();if(connection==h)connection=null;}}
 public void close(){closed=true;generation++;awaitingPermission=false;HttpURLConnection h=connection;if(h!=null)h.disconnect();worker.shutdownNow();}
 private static final class UpdateFailure extends Exception {UpdateFailure(String message){super(message);}}
}
